    "companyScale": "300-500人",
    "notes": "【岗位职责】\n负责供应链市场营销、开发和维护，根据客户个性化需求，向客户提供综合物流解决方案。\n1.客户需求分析与挖掘：深入理解并分析不同行业客户的供应链需求，特别是针对客户的个性化需求，通过定期沟通、市场调研等方式，精准捕捉并转化为客户可接受的供应链解决方案需求点。\n2.综合物流解决方案设计与实施：根据客户的具体需求，设计并实施包括仓储、运输、配送、库存管理等在内的综合物流解决方案。协调内部资源及外部合作伙伴，确保解决方案的高效执行和持续优化，以满足客户对成本、时效、质量等多方面的要求。\n3.客户关系管理与维护：建立并维护良好的客户关系，定期回访客户，收集反馈意见，及时响应并解决客户在供应链合作过程中遇到的问题，增强客户忠诚度和满意度。\n4.供应链数字化创新与优化：持续关注供应链管理领域的最新动态和技术发展，引入创新思路和技术手段，推动供应链流程优化、成本控制和服务升级，提升公司整体竞争力；能够发现业务痛点并运用数字化工具为供应链业务提质增效。\n5.跨部门协作与项目管理：与销售、运营、财务等部门紧密合作，确保供应链项目的顺利推进和跨部门资源的有效整合，共同达成公司业务目标。\n\n【任职条件】\n1、大学本科及以上学历应届毕业生；\n2、供应链管理、交通运输、物流管理、市场营销、计算机科学与技术、人工智能、数据分析、大数据等相关专业背景优先；\n3、有较强的责任心、学习能力、沟通能力、适应能力，有较强的目标导向，吃苦耐劳，积极乐观向上；\n4、良好的数据分析和项目方案撰写技能；\n5、具备沟通能力和客户服务意识，能够与客户建立长期稳定的合作关系；\n6、具备项目管理和团队协作能力，能够有效推动项目落地执行；\n7、岗位工作地点包含福建省内网点，将结合公司业务发展统筹调配，入职后需服从公司岗位及驻地安排。\n8、具有一定英语读写能力，熟悉office等办公软件应用。",
