    "examInfo": "",
    "companyScale": "50-100人",
    "notes": "【岗位职责】\n1.打造专业化的营销能力，协助部门负责人关键客户的营销与维护工作，根据营销计划完成客户拜访数及新客户签约数，维护客户关系，与客户保持良好沟通； \n2.协助部门负责人建立部门运营管理体系与业务操作标准规范，负责合同的签订及后续合同履行等事宜的跟进工作，打造物流领域内特性业务能力； \n3.定期收集并分析市场信息及竞争对手动态，及时发现潜在的新市场，汇报上级领导，协助部门负责人在从事领域建立产品管理体系与供应商体系； \n4.负责煤炭、矿石、钢材、件杂等大宗散货进出口物流项目全流程操作，落实单证、口岸、码头、货主、船东多方协同，跟踪船舶与货物动态，保障散货装卸、转运业务有序落地，做好风险管控与业务资料归档； \n5.完成领导交办的其他事项。\n【基本任职要求】\n1.硕士研究生及以上学历;\n2.境内院校应届毕业生需于2026年8月1日前取得毕业证书；\n3.年龄：28岁及以下；\n4.性别不限；\n5.责任心、事业心强，有良好的职业道德和政治素质;\n6.能接纳并融入公司的企业文化，尊重和认同公司的核心价值观；\n7.学习和逻辑能力强，积极向上，愿意学习人工智能、大数据等数字化工具，适配物流数字化、智能化业务发展需求;\n8.富有团队精神和沟通协作意识，理智客观;\n9.敢于接受挑战，做事持之以恒;\n10.大学英语四级及以上水平，有较好的外语听说读写能力和文字写作水平;\n11.遵纪守法、诚实守信、作风正派、身心健康，无不良记录。\n【加分条件】\n1.中共党员优先；\n2.外语能力突出，具备流利的外语沟通、书面写作能力者优先；\n3.具备数字化、绿色低碳等科技创新项目的建设经验优先；具备计算机、电子信息、大数据、人工智能相关领域实践，熟悉数字化物流应用场景者优先；具备物流、供应链等相关实习实践经验者优先。",
