    "notes": "【岗位名称】物业部电气技术员\n【招聘人数】1人\n【岗位职责】\n1.配电值守：负责公司变电所日常值班、运行监视、抄表巡检及台账记录，保障高低压供电系统安全稳定运行；\n2.日常电气运维：负责办公区、生产区用电线路、照明、配电箱柜的日常巡检、维护及故障抢修，排查用电安全隐患；\n3.电气设备维护：负责公司高杆灯、喷淋系统、污水处理系统、雾炮（雾桩）设备、厨房用电设备等电气设备的日常巡检、保养及故障维修；\n4.安全合规管理：严格遵守电气安全操作规程，落实停电、验电、挂牌、监护等安全措施，防范触电及设备安全事故；\n5.台账及其他工作：规范填写设备运行、维修、保养台账，做好岗位交接；服从工作调度，完成部门交办的临时工作任务。\n【基本任职要求】\n1.大学本科及以上学历；无电工相关操作证的，入职6个月内必须取得相应的操作证书；\n2.境内院校应届毕业生需于2027年8月1日前取得毕业证书、境外院校应届毕业生需于2027年12月31日前取得毕业证书的毕业生；\n3.责任心、事业心强，有良好的职业道德和政治素质；\n4.能接纳并融入公司的企业文化，尊重和认同公司的核心价值观:\n5.学习和逻辑能力强，积极向上；\n6.富有团队精神和沟通协作意识，理智客观；\n7.敢于接受挑战，做事持之以恒；\n8.遵纪守法、诚实守信、作风正派、身心健康，无不良记录。\n【加分条件】\n1.持有《低压电工作业操作证》、《高压电工证》或《高处作业证》；\n2.掌握电工基础及电气安全知识，熟悉电业安全工作规程，精通高低压配电系统原理；\n3.熟练识读电气图纸，会使用万用表、兆欧表、钳形电流表等专业电工仪表；\n4.熟悉电机、变频器、软启动器等常用电气元件，掌握喷淋、雾炮、高杆灯、污水处理、商用厨房电气设备的控制逻辑；\n5.具备PLC及触摸屏基础知识。",
