    "notes": "（一）岗位职责\n1.调研远洋船舶、国际航运业务场景需求，形成船舶通导产品需求分析报告、用户画像和场景定义，参与通导产品规划，为船舶通导产品研发提供场景与需求支撑；\n2.跟踪IMO、IHO、MASS Code、智能航运、智能船舶领域新技术新趋势，协助研判科研方向，明确研发着力点；\n3.结合公司船舶通导产品布局，提出科研立项方向建议，形成技术趋势简报、政策分析报告和科研选题建议；\n4.参与科研项目建议书、可行性研究报告、项目申报书、任务书、验收材料等编写与修订；\n5.参与创新联合体、高校院所合作、标准制定、专利软著等知识产权工作；协助组织技术交流、专家评审、示范应用和成果推广，支撑业务产品整体布局；\n6.完成领导交办的其他科研管理、材料撰写和协调任务。\n\n（二）任职要求\n1.大学本科及以上学历，国际航运、航运管理、交通运输等相关专业；\n2.掌握航运、船舶基础理论，熟悉远洋船舶作业模式及通导设备应用场景；\n3.具备较强的科研文字撰写与材料整合能力，能独立完成科研申报材料编写；\n4.具备行业前瞻思维，关注船舶通导、海事数字化、航运智能化等新技术趋势；\n5.逻辑清晰、学习能力强，具备良好的跨部门沟通协作能力；\n6.能熟练阅读国际海事公约、技术标准、英文文献。",
