    "notes": "（一）岗位职责\n1.依据工程规范编制检测计划，明确材料、实体质量的检测项目与方法；\n2.执行现场检测执，对建材（钢筋、混凝土、防水材料）进行抽样送检，记录检测数据（如抗压强度、耐久性指标）；\n运用仪器（如超声波探伤仪、回弹仪）对结构实体（桩基、混凝土构件）进行无损检测，评估施工质量；\n3.分析检测结果，编制检测报告，对不合格项提出处理建议（如结构加固、材料退场）；\n4.维护检测仪器精度，确保符合计量标准，跟踪行业新规（如检测方法更新）并落实；\n5.监督检测流程符合见证取样制度，留存原始记录与影像资料，配合监管部门抽查；\n6.为施工、监理方提供检测数据解读，参与质量事故分析，协助制定整改方案；\n7.完成领导交办的其他工作。\n\n（二）任职要求\n1.大学本科及以上学历，土木工程、港口航道与海岸工程、结构工程、岩土工程等工程类相关专业；\n2.熟练使用日常办公软件；\n3.熟练掌握所持证专业试验操作流程；\n4.具备较好的抗压能力、统筹能力、时间管理能力，责任心强，富有团队合作精神；\n5.了解水运工程监理等工作流程；\n6.身体健康，能胜任本职工作。",
