    "notes": "【职责描述】\n1、完成公司授权内的各项客户招揽与客户服务工作；\n2、按照公司日常管理要求开展工作；\n3、参加并完成公司执业前培训、后续职业培训、在岗培训等；\n4、熟练使用招商证券 APP 的功能，为客户及时解答有关 APP 的疑问，提高公司 APP 的渗透率；\n5、运用公司 APP 平台持续进行客户服务与营销的工作，完成公司要求的业绩指标；\n6、开发与维护银行渠道和有价值的非银行渠道；\n7、按照公司要求开展其他工作。\n【任职要求】\n1、通过证券从业人员资格考试者优先；\n2、学历原则上本科以上（经纪人学历可放宽至大专）；\n3、身体健康，品行端正，形象气质良好；\n4、表达能力和学习能力较强；\n5、认同招商证券文化与价值观，具有较强的风险合规意识；\n6、无不良从业记录、无违法犯罪记录，未持有证券监管机关禁止持有的证券资产；\n7、未同时与其他用人单位建立劳动关系或同时接受其他证券公司、银行、基金公司等金融证券机构或个人委托从事证券营销活动，或其他与公司要求的工作内容相同、相近的活动；\n8、具备能够按期保质完成公司授权的相关工作或公司下达的工作任务的能力；\n9、其他法律法规及公司规定的录用条件",
