    "companyScale": "1000-2000人",
    "notes": "（一）岗位职责\n1.负责气象导航相关AI算法设计、开发与落地，包括气象/海况时序预测、风浪流时空场建模、船舶航速衰减预测、航行路径智能优化算法研发；\n2.挖掘气象预报数据、海洋环境数据、船舶AIS、船舶主机/油耗、历史航行轨迹数据，开展数据清洗、特征工程、数据集构建。\n3.研究时序预测、时空数据建模、强化学习/启发式优化等算法，构建船舶航行环境预测模型与航线优化模型，降低船舶燃油消耗，提升航行安全性。\n4.对模型进行训练、调参、评估、验证；开展模型效果分析、误差溯源，持续迭代模型精度与泛化能力；对模型推理性能做优化。\n5.结合航海业务规则、气象海洋理论，融合传统气象导航理论与AI算法，支撑航线推荐、风险预警、航次模拟等核心业务功能。\n6.对接后端、前端、海事业务团队，输出算法方案、接口、技术文档；支撑算法工程化部署，解决上线后模型推理、数据漂移等问题。\n7.完成领导交办的其他工作任务。\n\n（二）任职要求\n1.硕士研究生及以上学历，计算机、人工智能、应用数学、海洋科学、大气科学、航海技术、遥感等相关专业；\n2.具备扎实机器学习、深度学习基础，熟悉时序模型（LSTM/Transformer等）、回归、分类等算法原理，掌握特征工程、模型评估方法；\n3.熟练使用Python，熟悉Pandas、NumPy、Scikit-learn、PyTorch/TensorFlow等AI工具栈；\n4.熟悉时空数据处理，了解GIS、网格气象数据（GRIB、NetCDF）处理优先；\n5.具备数据分析能力，能够独立完成数据处理、模型实验、指标对比；\n6.具备良好数学基础及算法实验设计、问题定位能力。",
