    "notes": "岗位职责：\n1、协助开展全面从严治党、党风廉政建设和反腐败日常工作，做好材料起草、台账整理、信息报送等基础事务；\n2、协助开展廉政宣传教育、廉洁文化建设，组织廉政学习、警示教育、廉政谈话等活动，做好方案筹备、会务及资料归档；\n3、协助开展日常监督工作，参与廉政风险排查、制度执行监督、专项督查，做好监督记录、资料汇总；\n4、协助受理信访举报线索登记、流转管理，按要求做好线索台账维护，落实保密管理；协助做好案件查办相关资料收集、文书整理、案卷归档；\n5、负责纪检档案、廉政档案管理维护，做好纪检相关报表统计、数据汇总；参与纪检数字化平台、监督台账系统建设、运维、表单开发，优化纪检业务线上流程；\n6、协助完善纪检内控管理制度、工作流程，落实巡察、审计、纪检整改相关资料归集、跟踪闭环；\n7、完成部门交办的其他纪检相关工作。\n\n\n任职条件：\n1、大学本科及以上学历应届毕业生。党务、社会学、哲学、计算机等相关专业优先；\n2、中共党员，政治立场坚定，严守政治纪律和政治规矩，保密意识极强；责任心强，严谨细致，具备良好抗压能力、团队协作意识，文字表达、沟通协调能力良好；\n3、了解基础公文写作，具备数字化思维，能够运用信息化工具搭建、优化业务台账与线上管理平台；熟悉数据整理、表单制作、流程搭建者优先；\n4、熟练使用 Office、数据库、低代码平台等工具，具备平台搭建、数据处理、自动化报表制作能力优先；\n5、在校期间有信息化系统搭建、数字化台账开发、数据治理相关项目或实习经历者优先。",
