    "examInfo": "",
    "companyScale": "50-100人",
    "notes": "【岗位职责】\n1.根据上级公司指导，结合公司实际情况编制财务预算管理制度及体系，推进全面预算管理；  \n2.负责公司快报、月报、预算、决算等财务报表编制；\n3. 严格执行财务制度，负责费用报销审核、票据管理、纳税申报、税控设备维护及税企对接，及时传达落实财税新政策；\n4. 协助完善财务业务流程与内控体系，排查化解财务风险，处理日常财务突发问题，维系内外财务对接关系；\n5. 落实岗位安全、学习考核等工作，完成领导交办的其他财务相关工作。\n\n【基本任职要求】\n1.硕士研究生及以上学历；\n2.境内院校应届毕业生需于2026年8月1日前取得毕业证书；\n3.年龄：28岁及以下；\n4.性别不限；\n5.责任心、事业心强，具有良好的职业道德和政治素质;\n6.能接纳并融入公司的企业文化，尊重和认同公司的核心价值观；\n7.学习和逻辑能力强，积极向上;\n8.富有团队精神和沟通协作意识，理智客观;\n9.敢于接受挑战，做事持之以恒;\n8.大学英语四级及以上水平，有较好的外语听说读写能力和文字写作水平;\n9.遵纪守法、诚实守信、作风正派、身心健康，无不良记录。\n\n【加分条件】\n1.中共党员优先；\n2.持有初级会计、税务师、CPA等财会相关职业资格证书优先;\n3.具备企业财务、出纳、税务核算相关实习或实操工作经验者优先;\n4.熟练掌握财务软件、办公数据分析工具，熟悉财税法律法规及国企/物流行业财务流程者优先。",
