    "applyLink": "https://coscoshipping.iguopin.com/job/detail?id=218791206979633428",
    "noticeLink": "https://coscoshipping.iguopin.com/job",
    "examInfo": "",
    "companyScale": "500-1000人",
    "notes": "任职条件：\n1.硕士研究生及以上学历；具备大型项目落地经验或成功工程案例者优先，有机器人切割、打磨、焊接相关项目实战经验者优先；\n2.机器人工程、 电气工程及其自动化、自动化、机械电子工程、机械设计制造及其自动化等相关专业；\n3. 熟悉工件表面 3D 点云图像处理技术，能够基于 3D 点云处理结果完成六轴机器人作业路径规划；\n4. 掌握机器人多坐标系转换，熟悉多坐标系下机器人运动路径规划与运动控制方法；\n5. 掌握 PLC 编程、伺服驱动控制等自动化核心技术。\n\n岗位职责：\n1. 负责多轴关节机器人项目的整体功能规划、方案设计，基于 2D/3D 视觉相机扫描采集数据，完成六轴关节机器人运动控制开发、轨迹算法优化及路径规划编程，确保机器人精准执行作业任务；\n2. 开展机器人相关技术预研与方案验证，对视觉+六轴机器人集成方案进行仿真、测试与调试，持续优化机器人运动精度、运行稳定性；\n3. 跟踪机器人、视觉传感相关新技术，评估技术可行性，输出技术评估报告，支撑自动化产品迭代升级；\n4. 负责研发项目全生命周期管理，主导项目调研、立项申报、合作方评估与选型、需求变更管控等全流程工作，对项目范围、成本、进度、质量与风险进行全面把控；\n5. 负责项目内外部资源统筹与协调，对接跨部门团队及合作方，参与技术方案评审与优化，推进关键技术落地与现场问题解决，保障项目按计划交付；\n6. 负责项目关键文档编制与管理，独立撰写立项报告、技术方案、进度汇报、结题材料等，确保文档规范、完整、可追溯；\n6. 具备电子电气相关专业基础，可独立完成电机、线缆等器件的方案选型、开发、测试验证及迭代维护工作；\n7. 能够识读电气原理图，熟悉电气安全相关标准；掌握模数转换、信号放大、信号滤波等软硬件基础原理；\n8. 具备良好的项目文档撰写能力、跨部门沟通协调能力，逻辑思维清晰，具备较强问题分析与现场技术问题排查能力。",
