    "notes": "（一）岗位职责\n1.负责雷达信号处理算法设计、仿真、实现与验证，包括脉冲压缩、动目标检测MTD、恒虚警检测CFAR、杂波抑制、目标提取、测角测距等算法；\n2.开展雷达回波信号分析，研究海杂波、多径干扰、噪声抑制算法，提升海上目标检测能力；\n3.使用MATLAB/Python完成算法建模、仿真验证；将成熟算法工程化到DSP、FPGA或嵌入式平台；\n4.参与雷达系统方案论证，分析雷达作用距离、测距/测角精度、虚警率、检测概率等系统指标；\n5.负责雷达外场实测数据采集、分析，定位目标漏检、虚警、目标分裂等问题，迭代优化信号处理算法；\n6.完成领导交办的其他工作任务。\n\n（二）任职要求\n1.硕士研究生及以上学历，电子信息工程、通信工程、雷达工程、信号与信息处理等相关专业；\n2.扎实的数字信号处理理论基础：傅里叶变换、滤波器设计、随机信号分析、统计检测理论；\n3.熟悉雷达基本原理，掌握脉冲压缩、MTD、CFAR、杂波抑制等经典雷达信号处理算法；\n4.熟练使用MATLAB进行算法仿真，具备回波数据分析能力；\n5.熟悉雷达系统指标（检测概率、虚警率、测距测角精度）；\n6.具备良好的问题分析能力，能够基于实测数据定位算法问题。",
